extends Node3D

@export var grid_size: int = 20
@export var update_interval: float = 0.4
@export var alive_probability: float = 0.3

var _cells: Array[PackedByteArray] = []  # 2D: rows of cells
var _generation: int = 1

func _initialize_grid() -> void:
	_cells.clear()
	for y in range(grid_size):
		var row := PackedByteArray()
		row.resize(grid_size)
		for x in range(grid_size):
			row[x] = 1 if randf() < alive_probability else 0
		_cells.append(row)

func _step() -> void:
	var next_cells: Array[PackedByteArray] = []
	for y in range(grid_size):
		var row := PackedByteArray()
		row.resize(grid_size)
		for x in range(grid_size):
			var neighbors = _count_neighbors(x, y)
			var current = _cells[y][x]

			# Conway's Game of Life (B3/S23)
			if current == 1:
				row[x] = 1 if (neighbors == 2 or neighbors == 3) else 0
			else:
				row[x] = 1 if neighbors == 3 else 0
		next_cells.append(row)
	_cells = next_cells
	_generation += 1

var _timer: float = 0.0

func _process(delta: float) -> void:
	_timer += delta
	if _timer >= update_interval:
		_timer = 0.0
		_step()
		_render_cells()
		_update_status()

func _update_status() -> void:
	_status_label.text = "Gen %d | alive: %d" % [
		_generation, _count_alive()
	]

const MAT_ALIVE := preload(
	"res://commons/resourses/materials/noc_vr/noc_vr_pink_primary.tres"
)
const MAT_DEAD := preload(
	"res://commons/resourses/materials/noc_vr/noc_vr_fishtank_glass.tres"
)

func _render_cells() -> void:
	for y in range(grid_size):
		for x in range(grid_size):
			var cell_node = _cell_instances[y][x]
			if _cells[y][x] == 1:
				cell_node.material_override = MAT_ALIVE
			else:
				cell_node.material_override = MAT_DEAD

